//! `eb-local audit-isa`: the instructions in an installed prefix that need a
//! CPU feature the target does not have. Every ELF file under the path is
//! disassembled by objdump; each instruction's mnemonic, encoding and vector
//! width select the features it needs from tables generated by
//! tools/isa_tables/gen.py, and a feature missing from the target's set is a
//! violation. Code that selects its instruction set at run time is listed in
//! an allow file and reported as dispatch, which does not fail the audit.
const std = @import("std");
const common = @import("zig_common");
const sys = common.sys;
const fsx = common.fsx;
const proc = common.proc;
const cli = common.cli;
const jsonout = @import("jsonout.zig");
const Allocator = std.mem.Allocator;

const x86_tsv = @embedFile("isa/x86_features.tsv");
const aarch64_tsv = @embedFile("isa/aarch64_rules.tsv");
const targets_tsv = @embedFile("isa/targets.tsv");
const default_allow = @embedFile("isa/dispatch-allow.txt");

/// A set of features, one bit per interned name.
pub const Mask = u256;

/// The architectures the audit reads: the machine of the ELF file selects one.
pub const Arch = enum {
    x86_64,
    aarch64,

    fn machine(self: Arch) u16 {
        return switch (self) {
            .x86_64 => 62,
            .aarch64 => 183,
        };
    }
};

/// An EESSI software subdirectory, its architecture and the features its CPU has.
pub const Target = struct { name: []const u8, arch: Arch, has: Mask };

const Span = struct { start: u32, len: u32 };
const X86Row = struct { enc: u8, width: u16, need: Mask, unk: Mask };
const need_sve: u8 = 1;
const need_nosve: u8 = 2;
const need_hreg: u8 = 4;
const Rule = struct { flags: u8, op: []const u8, feat: u8 };

/// Why `Db.load` read nothing: memory, or a table the generator did not write.
pub const LoadError = Allocator.Error || error{BadTable};

/// The tables of the generator, parsed.
pub const Db = struct {
    names: std.ArrayList([]const u8) = .empty,
    ids: std.StringHashMapUnmanaged(u8) = .empty,
    x86_index: std.StringHashMapUnmanaged(Span) = .empty,
    x86_rows: std.ArrayList(X86Row) = .empty,
    a64_index: std.StringHashMapUnmanaged(std.ArrayList(Rule)) = .empty,
    a64_any: std.ArrayList(Rule) = .empty,
    targets: std.ArrayList(Target) = .empty,
    shstk: u8 = 0,

    fn intern(db: *Db, a: Allocator, name: []const u8) LoadError!u8 {
        if (db.ids.get(name)) |id| return id;
        if (db.names.items.len >= 256) return error.BadTable;
        const id: u8 = @intCast(db.names.items.len);
        try db.names.append(a, name);
        try db.ids.put(a, name, id);
        return id;
    }

    fn maskOf(db: *Db, a: Allocator, list: []const u8, unknown: ?*Mask) LoadError!Mask {
        var m: Mask = 0;
        var it = std.mem.splitScalar(u8, list, ',');
        while (it.next()) |f| {
            if (f.len == 0) continue;
            if (f[0] == '?') {
                const id = try db.intern(a, f[1..]);
                if (unknown) |u| u.* |= bit(id);
            } else m |= bit(try db.intern(a, f));
        }
        return m;
    }

    /// Parse the embedded tables into a database allocated from `a`.
    pub fn load(a: Allocator) LoadError!*Db {
        const db = try a.create(Db);
        db.* = .{};
        db.shstk = try db.intern(a, "shstk");

        var current: []const u8 = "";
        var start: u32 = 0;
        var lines = std.mem.splitScalar(u8, x86_tsv, '\n');
        while (lines.next()) |line| {
            if (line.len == 0 or line[0] == '#') continue;
            var f = std.mem.splitScalar(u8, line, '\t');
            const mn = f.next() orelse return error.BadTable;
            const enc = f.next() orelse return error.BadTable;
            const width = f.next() orelse return error.BadTable;
            const feats = f.next() orelse return error.BadTable;
            if (enc.len != 1) return error.BadTable;
            if (!std.mem.eql(u8, mn, current)) {
                if (current.len > 0) try db.x86_index.put(a, current, .{ .start = start, .len = @intCast(db.x86_rows.items.len - start) });
                current = mn;
                start = @intCast(db.x86_rows.items.len);
            }
            var unk: Mask = 0;
            const need = try db.maskOf(a, feats, &unk);
            try db.x86_rows.append(a, .{
                .enc = enc[0],
                .width = std.fmt.parseInt(u16, width, 10) catch return error.BadTable,
                .need = need,
                .unk = unk,
            });
        }
        if (current.len > 0) try db.x86_index.put(a, current, .{ .start = start, .len = @intCast(db.x86_rows.items.len - start) });

        lines = std.mem.splitScalar(u8, aarch64_tsv, '\n');
        while (lines.next()) |line| {
            if (line.len == 0 or line[0] == '#') continue;
            var f = std.mem.splitScalar(u8, line, '\t');
            const mn = f.next() orelse return error.BadTable;
            const cond = f.next() orelse return error.BadTable;
            const feat = f.next() orelse return error.BadTable;
            var rule: Rule = .{ .flags = 0, .op = "", .feat = try db.intern(a, feat) };
            var tests = std.mem.splitScalar(u8, cond, ',');
            while (tests.next()) |t| {
                if (t.len == 0) continue;
                if (std.mem.eql(u8, t, "sve")) {
                    rule.flags |= need_sve;
                } else if (std.mem.eql(u8, t, "nosve")) {
                    rule.flags |= need_nosve;
                } else if (std.mem.eql(u8, t, "hreg")) {
                    rule.flags |= need_hreg;
                } else if (std.mem.startsWith(u8, t, "op=")) {
                    rule.op = t[3..];
                } else return error.BadTable;
            }
            if (std.mem.eql(u8, mn, "*")) {
                try db.a64_any.append(a, rule);
            } else {
                const gop = try db.a64_index.getOrPut(a, mn);
                if (!gop.found_existing) gop.value_ptr.* = .empty;
                try gop.value_ptr.append(a, rule);
            }
        }

        lines = std.mem.splitScalar(u8, targets_tsv, '\n');
        while (lines.next()) |line| {
            if (line.len == 0 or line[0] == '#') continue;
            var f = std.mem.splitScalar(u8, line, '\t');
            const name = f.next() orelse return error.BadTable;
            const arch = f.next() orelse return error.BadTable;
            const feats = f.next() orelse "";
            try db.targets.append(a, .{
                .name = name,
                .arch = std.meta.stringToEnum(Arch, arch) orelse return error.BadTable,
                .has = try db.maskOf(a, feats, null),
            });
        }
        return db;
    }

    /// The id a feature name has, if the tables mention it.
    pub fn idOf(db: *const Db, feature_name: []const u8) ?u8 {
        return db.ids.get(feature_name);
    }

    /// The name of a feature id.
    pub fn nameOf(db: *const Db, feature: u8) []const u8 {
        return db.names.items[feature];
    }

    /// The target `want` names: a full EESSI subdirectory, or a trailing
    /// part of one that only one subdirectory ends with.
    pub fn target(db: *const Db, want: []const u8) ?Target {
        for (db.targets.items) |t| if (std.mem.eql(u8, t.name, want)) return t;
        var found: ?Target = null;
        for (db.targets.items) |t| {
            if (t.name.len > want.len and t.name[t.name.len - want.len - 1] == '/' and std.mem.endsWith(u8, t.name, want)) {
                if (found != null) return null;
                found = t;
            }
        }
        return found;
    }
};

fn bit(id: u8) Mask {
    return @as(Mask, 1) << id;
}

/// What one instruction needs: the features the target must have, the
/// features the tables do not classify, and whether the mnemonic is unknown
/// for a vector encoding.
pub const Verdict = struct {
    need: Mask = 0,
    unclassified: Mask = 0,
    unknown_mnemonic: bool = false,
    zmm: bool = false,
};

/// One line of disassembly.
pub const Line = struct {
    address: u64,
    bytes: []const u8,
    mnemonic: []const u8,
    operands: []const u8,
};

fn isHex(c: u8) bool {
    return std.ascii.isHex(c);
}

fn isPrefix(word: []const u8) bool {
    const prefixes = [_][]const u8{ "lock", "rep", "repz", "repnz", "repe", "repne", "bnd", "notrack", "data16", "addr32", "xacquire", "xrelease", "cs", "ds", "es", "ss", "fs", "gs" };
    for (prefixes) |p| if (std.mem.eql(u8, word, p)) return true;
    return std.mem.startsWith(u8, word, "rex");
}

fn trimSpace(s: []const u8) []const u8 {
    return std.mem.trim(u8, s, " \t\r");
}

/// Parse `ADDRESS:<tab or spaces>BYTES<tab>MNEMONIC OPERANDS` as GNU objdump
/// and llvm-objdump print it; null for any other line. Instruction prefixes
/// before the mnemonic are skipped, and a symbol or comment after the
/// operands is cut.
pub fn parseLine(line: []const u8) ?Line {
    var i: usize = 0;
    while (i < line.len and line[i] == ' ') i += 1;
    const digits = i;
    var address: u64 = 0;
    while (i < line.len and isHex(line[i])) : (i += 1) {
        address = std.math.shlExact(u64, address, 4) catch return null;
        address |= std.fmt.charToDigit(line[i], 16) catch return null;
    }
    if (i == digits or i >= line.len or line[i] != ':') return null;
    const rest = std.mem.trimStart(u8, line[i + 1 ..], " \t");
    const tab = std.mem.findScalar(u8, rest, '\t') orelse return null;
    const bytes = trimSpace(rest[0..tab]);
    if (bytes.len == 0 or !isHex(bytes[0])) return null;
    var text = trimSpace(rest[tab + 1 ..]);
    var mnemonic: []const u8 = "";
    while (true) {
        const end = std.mem.findAny(u8, text, " \t") orelse text.len;
        mnemonic = text[0..end];
        text = trimSpace(text[end..]);
        if (mnemonic.len == 0 or !isPrefix(mnemonic) or text.len == 0) break;
    }
    if (mnemonic.len == 0) return null;
    const cut = std.mem.findAny(u8, text, "<#") orelse text.len;
    return .{ .address = address, .bytes = bytes, .mnemonic = mnemonic, .operands = trimSpace(text[0..cut]) };
}

/// The encoding of an x86-64 instruction from its bytes: V for VEX, E for
/// EVEX, X for XOP, L for the rest.
pub fn x86Encoding(bytes: []const u8) u8 {
    var it = std.mem.tokenizeScalar(u8, bytes, ' ');
    var first: ?u8 = null;
    while (it.next()) |tok| {
        const b = std.fmt.parseInt(u8, tok, 16) catch return 'L';
        if (first == null) {
            switch (b) {
                0x66, 0xf2, 0xf3, 0x2e, 0x36, 0x3e, 0x26, 0x64, 0x65, 0x67, 0xf0 => continue,
                0x40...0x4f => continue,
                0x62 => return 'E',
                0xc4, 0xc5 => return 'V',
                0x8f => first = b,
                else => return 'L',
            }
        } else return if (b & 0x1f >= 8) 'X' else 'L';
    }
    return 'L';
}

fn containsLower(hay: []const u8, needle: []const u8) bool {
    if (needle.len > hay.len) return false;
    var i: usize = 0;
    while (i + needle.len <= hay.len) : (i += 1) {
        var ok = true;
        for (needle, 0..) |n, k| {
            if (std.ascii.toLower(hay[i + k]) != n) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    }
    return false;
}

/// The widest vector register or memory operand the operands name, 0 for none.
pub fn vectorWidth(operands: []const u8) u16 {
    if (containsLower(operands, "zmm")) return 512;
    if (containsLower(operands, "ymm")) return 256;
    if (containsLower(operands, "xmm")) return 128;
    return 0;
}

fn inList(word: []const u8, list: []const []const u8) bool {
    for (list) |w| if (std.mem.eql(u8, w, word)) return true;
    return false;
}

const cmp_predicates = [_][]const u8{
    "eq",    "lt",     "le",     "unord",    "neq",    "nlt",    "nle",    "ord",
    "eq_uq", "nge",    "ngt",    "false",    "neq_oq", "ge",     "gt",     "true",
    "eq_os", "lt_oq",  "le_oq",  "unord_s",  "neq_us", "nlt_uq", "nle_uq", "ord_s",
    "eq_us", "nge_uq", "ngt_uq", "false_os", "neq_os", "ge_oq",  "gt_oq",  "true_us",
};
const int_predicates = [_][]const u8{ "eq", "lt", "le", "ne", "neq", "nlt", "nle", "ge", "gt", "false", "true" };
const int_types = [_][]const u8{ "ub", "uw", "ud", "uq", "b", "w", "d", "q" };

/// The mnemonic of the instruction an assembler alias stands for
/// (vcmpltps, vpcmpnleub, vpcomltb, pclmullqlqdq), written into `buf`.
pub fn aliasOf(mn: []const u8, buf: *[32]u8) ?[]const u8 {
    if (std.mem.endsWith(u8, mn, "dq") and (std.mem.startsWith(u8, mn, "pclmul") or std.mem.startsWith(u8, mn, "vpclmul"))) {
        const v = mn[0] == 'v';
        const mid = mn[if (v) 7 else 6 .. mn.len - 2];
        if (mid.len == 4 and (mid[0] == 'l' or mid[0] == 'h') and mid[1] == 'q' and (mid[2] == 'l' or mid[2] == 'h') and mid[3] == 'q')
            return std.fmt.bufPrint(buf, "{s}pclmulqdq", .{if (v) "v" else ""}) catch null;
        return null;
    }
    const suffixes = [_][]const u8{ "ps", "pd", "ss", "sd" };
    for ([_][]const u8{ "vcmp", "cmp" }) |stem| {
        if (!std.mem.startsWith(u8, mn, stem) or mn.len < stem.len + 2) continue;
        const tail = mn[mn.len - 2 ..];
        if (!inList(tail, &suffixes)) continue;
        if (inList(mn[stem.len .. mn.len - 2], &cmp_predicates))
            return std.fmt.bufPrint(buf, "{s}{s}", .{ stem, tail }) catch null;
    }
    for ([_][]const u8{ "vpcmp", "vpcom" }) |stem| {
        if (!std.mem.startsWith(u8, mn, stem)) continue;
        const rest = mn[stem.len..];
        for (int_types) |t| {
            if (!std.mem.endsWith(u8, rest, t) or rest.len == t.len) continue;
            if (inList(rest[0 .. rest.len - t.len], &int_predicates))
                return std.fmt.bufPrint(buf, "{s}{s}", .{ stem, t }) catch null;
        }
    }
    return null;
}

fn x86Row(db: *const Db, mn: []const u8, enc: u8, width: u16) ?X86Row {
    const span = db.x86_index.get(mn) orelse return null;
    const rows = db.x86_rows.items[span.start..][0..span.len];
    var merged: X86Row = .{ .enc = enc, .width = width, .need = 0, .unk = 0 };
    var any = false;
    for (rows) |r| {
        if (r.enc != enc) continue;
        if (r.width == width) return r;
        merged.need |= r.need;
        merged.unk |= r.unk;
        any = true;
    }
    return if (any) merged else null;
}

/// What an x86-64 instruction needs.
pub fn classifyX86(db: *const Db, ln: Line) Verdict {
    var v: Verdict = .{};
    const mn = ln.mnemonic;
    if (mn.len == 0 or mn[0] == '.' or mn[0] == '(' or mn[0] == '<') return v;
    const enc = x86Encoding(ln.bytes);
    const width = vectorWidth(ln.operands);
    v.zmm = width == 512;
    var buf: [32]u8 = undefined;
    const row = x86Row(db, mn, enc, width) orelse blk: {
        if (aliasOf(mn, &buf)) |alt| {
            if (x86Row(db, alt, enc, width)) |r| break :blk r;
        }
        break :blk null;
    };
    if (row) |r| {
        v.need = r.need;
        v.unclassified = r.unk;
        // RDSSP and INCSSP run as NOPs without shadow stacks; the unwinder
        // uses them behind a check.
        if (inList(mn, &.{ "rdsspd", "rdsspq", "incsspd", "incsspq" })) v.need &= ~bit(db.shstk);
    } else if (enc != 'L') {
        v.unknown_mnemonic = true;
    }
    return v;
}

fn registerIn(operands: []const u8, letter: u8, max: u8) bool {
    var i: usize = 0;
    while (i < operands.len) {
        if (!std.ascii.isAlphanumeric(operands[i])) {
            i += 1;
            continue;
        }
        const start = i;
        while (i < operands.len and std.ascii.isAlphanumeric(operands[i])) i += 1;
        const tok = operands[start..i];
        if (tok.len >= 2 and tok.len <= 3 and tok[0] == letter) {
            const n = std.fmt.parseInt(u8, tok[1..], 10) catch continue;
            if (n <= max) return true;
        }
    }
    return false;
}

/// What an aarch64 instruction needs: the feature of the first rule its
/// mnemonic and operands match.
pub fn classifyA64(db: *const Db, ln: Line) Verdict {
    var v: Verdict = .{};
    const mn = ln.mnemonic;
    if (mn.len == 0 or mn[0] == '.' or mn[0] == '<' or mn[0] == '(') return v;
    const sve = registerIn(ln.operands, 'z', 31) or registerIn(ln.operands, 'p', 15);
    const hreg = registerIn(ln.operands, 'h', 31);
    if (db.a64_index.get(mn)) |rules| {
        for (rules.items) |r| if (ruleMatches(r, ln.operands, sve, hreg)) {
            v.need = bit(r.feat);
            return v;
        };
    }
    for (db.a64_any.items) |r| if (ruleMatches(r, ln.operands, sve, hreg)) {
        v.need = bit(r.feat);
        return v;
    };
    return v;
}

fn ruleMatches(r: Rule, operands: []const u8, sve: bool, hreg: bool) bool {
    if (r.flags & need_sve != 0 and !sve) return false;
    if (r.flags & need_nosve != 0 and sve) return false;
    if (r.flags & need_hreg != 0 and !hreg) return false;
    if (r.op.len > 0 and !containsLower(operands, r.op)) return false;
    return true;
}

/// A package whose files hold code chosen at run time, and the features that
/// code may use.
pub const AllowEntry = struct { needle: []const u8, mask: Mask };

/// Parse "PACKAGE feature[,feature...]  # reason" lines. A feature the
/// tables do not name is ignored.
pub fn parseAllow(a: Allocator, db: *const Db, text: []const u8) Allocator.Error![]const AllowEntry {
    var out: std.ArrayList(AllowEntry) = .empty;
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |raw| {
        const line = if (std.mem.findScalar(u8, raw, '#')) |h| raw[0..h] else raw;
        var words = std.mem.tokenizeAny(u8, line, " \t\r");
        const pkg = words.next() orelse continue;
        const feats = words.next() orelse continue;
        var mask: Mask = 0;
        var it = std.mem.splitScalar(u8, feats, ',');
        while (it.next()) |f| if (db.idOf(f)) |fid| {
            mask |= bit(fid);
        };
        try out.append(a, .{ .needle = try std.fmt.allocPrint(a, "/software/{s}/", .{pkg}), .mask = mask });
    }
    return out.items;
}

/// True when a file under /software/PACKAGE/ may use the feature.
pub fn allowed(entries: []const AllowEntry, path: []const u8, feature: u8) bool {
    for (entries) |e| {
        if (e.mask & bit(feature) == 0) continue;
        if (std.mem.find(u8, path, e.needle) != null) return true;
    }
    return false;
}

// ---- report ---------------------------------------------------------------

/// One feature a file needs and the target lacks: how many instructions, the first
/// one, and whether the allow list covers it.
pub const Finding = struct {
    feature: []const u8,
    count: u64,
    address: []const u8,
    instruction: []const u8,
    dispatch: bool,
};
/// A file with at least one finding.
pub const FileReport = struct {
    path: []const u8,
    instructions: u64,
    zmm: u64,
    findings: []const Finding,
};
/// A feature or mnemonic the tables cannot judge, and how often it occurs.
pub const Unclassified = struct { name: []const u8, kind: []const u8, count: u64 };
/// A file or directory the audit could not read or disassemble, and why.
pub const Problem = struct { path: []const u8, message: []const u8 };
/// The result of an audit, and the document `--json` prints.
pub const Report = struct {
    schema_version: u32 = jsonout.schema_version,
    kind: []const u8 = "audit-isa",
    target: []const u8,
    arch: []const u8,
    files_audited: u64,
    files_skipped: u64,
    instructions: u64,
    zmm: u64,
    violation_count: u64,
    dispatch_count: u64,
    failed: bool,
    files: []const FileReport,
    unclassified: []const Unclassified,
    errors: []const Problem,
};

/// The text `audit-isa` prints for a report.
pub fn renderText(a: Allocator, r: Report) Allocator.Error![]const u8 {
    var out: std.ArrayList(u8) = .empty;
    try out.print(a, "eb-local audit-isa: target {s}, {d} ELF files, {d} instructions\n", .{ r.target, r.files_audited, r.instructions });
    for (r.files) |f| for (f.findings) |x| {
        try out.print(a, "{s}: {s} x{d} in {s}, first at {s}: {s}\n", .{ if (x.dispatch) "dispatch" else "violation", x.feature, x.count, f.path, x.address, x.instruction });
    };
    for (r.unclassified) |u| try out.print(a, "unclassified {s}: {s} x{d}\n", .{ u.kind, u.name, u.count });
    for (r.errors) |e| try out.print(a, "error: {s}: {s}\n", .{ e.path, e.message });
    if (r.zmm > 0) try out.print(a, "eb-local audit-isa: {d} zmm instructions\n", .{r.zmm});
    if (r.violation_count == 0) {
        try out.print(a, "eb-local audit-isa: no instruction beyond {s}\n", .{r.target});
    } else {
        var n: usize = 0;
        for (r.files) |f| for (f.findings) |x| {
            if (!x.dispatch) {
                n += 1;
                break;
            }
        };
        try out.print(a, "eb-local audit-isa: {d} instruction(s) beyond {s} in {d} file(s)\n", .{ r.violation_count, r.target, n });
    }
    return out.items;
}

// ---- running objdump ------------------------------------------------------

const Tool = struct { exe: []const u8, gnu: bool };

fn lessStr(_: void, x: []const u8, y: []const u8) bool {
    return std.mem.lessThan(u8, x, y);
}

fn elfMachine(path: []const u8, follow: bool) ?u16 {
    const f = fsx.openRegular(fsx.cwd, path, follow) catch return null;
    defer sys.close(f.fd);
    var head: [20]u8 = undefined;
    var n: usize = 0;
    while (n < head.len) {
        const got = sys.read(f.fd, head[n..]) catch return null;
        if (got == 0) return null;
        n += got;
    }
    if (!std.mem.eql(u8, head[0..4], "\x7fELF") or head[4] != 2 or head[5] != 1) return null;
    return std.mem.readInt(u16, head[18..20], .little);
}

const walk_depth_max = 64;

fn walk(a: Allocator, dir_path: []const u8, files: *std.ArrayList([]const u8), unreadable: *std.ArrayList(Problem), depth: usize) void {
    if (depth > walk_depth_max) {
        unreadable.append(a, .{ .path = dir_path, .message = "too deep to audit" }) catch oom();
        return;
    }
    const fd = fsx.openDir(fsx.cwd, dir_path, false) catch |e| {
        unreadable.append(a, .{ .path = dir_path, .message = sys.describe(e) }) catch oom();
        return;
    };
    defer sys.close(fd);
    var names: std.ArrayList([]const u8) = .empty;
    var it = fsx.DirIter.init(a, fd) catch oom();
    while (true) {
        const entry = it.next() catch |e| {
            unreadable.append(a, .{ .path = dir_path, .message = sys.describe(e) }) catch oom();
            break;
        } orelse break;
        names.append(a, a.dupe(u8, entry.name) catch oom()) catch oom();
    }
    std.mem.sort([]const u8, names.items, {}, lessStr);
    for (names.items) |name| {
        const st = fsx.statAt(fd, name, false) catch |e| {
            unreadable.append(a, .{ .path = std.fs.path.join(a, &.{ dir_path, name }) catch oom(), .message = sys.describe(e) }) catch oom();
            continue;
        };
        if (st.isLink()) continue;
        const path = std.fs.path.join(a, &.{ dir_path, name }) catch oom();
        if (st.isDir()) {
            walk(a, path, files, unreadable, depth + 1);
        } else if (st.isReg()) {
            files.append(a, path) catch oom();
        }
    }
}

fn oom() noreturn {
    cli.die("eb-local", "out of memory", .{});
}

fn runCapture(a: Allocator, exe: []const u8, args: []const []const u8, envp: proc.Envp) ?proc.Result {
    var argv: std.ArrayList([]const u8) = .empty;
    argv.append(a, exe) catch oom();
    argv.appendSlice(a, args) catch oom();
    return proc.run(a, exe, argv.items, envp, .{ .stdout_limit = 1 << 20, .stdout_overflow = .truncate, .stderr_limit = 4096, .timeout_ms = 30_000 }) catch null;
}

/// True when `exe` reads the object format of `arch`: GNU objdump lists its
/// formats with -i, llvm-objdump its targets with --version.
fn supports(a: Allocator, exe: []const u8, arch: Arch, envp: proc.Envp) ?bool {
    if (runCapture(a, exe, &.{"-i"}, envp)) |r| {
        if (r.term == .exited and r.term.exited == 0) {
            const needle = switch (arch) {
                .x86_64 => "elf64-x86-64",
                .aarch64 => "elf64-littleaarch64",
            };
            return if (std.mem.find(u8, r.stdout, needle) != null) true else false;
        }
    }
    const r = runCapture(a, exe, &.{"--version"}, envp) orelse return null;
    if (r.term != .exited or r.term.exited != 0) return null;
    return containsLower(r.stdout, switch (arch) {
        .x86_64 => "x86-64",
        .aarch64 => "aarch64 ",
    });
}

fn pickTool(a: Allocator, arch: Arch, override: ?[]const u8, path_env: []const u8, envp: proc.Envp) ?Tool {
    if (override) |o| {
        const exe = (proc.resolveExecutable(a, o, path_env) catch null) orelse return null;
        return .{ .exe = exe, .gnu = !std.mem.startsWith(u8, std.fs.path.basename(exe), "llvm-") };
    }
    const names: []const []const u8 = switch (arch) {
        .x86_64 => &.{ "objdump", "x86_64-linux-gnu-objdump", "llvm-objdump" },
        .aarch64 => &.{ "aarch64-linux-gnu-objdump", "objdump", "llvm-objdump" },
    };
    for (names) |n| {
        const exe = (proc.which(a, n, path_env) catch null) orelse continue;
        if (supports(a, exe, arch, envp) orelse false) return .{ .exe = exe, .gnu = !std.mem.startsWith(u8, n, "llvm-") };
    }
    return null;
}

/// Disassemble `file` into `out_path`; null on success, else why not.
fn disassemble(a: Allocator, tool: Tool, arch: Arch, file: []const u8, out_path: []const u8, envp: proc.Envp) ?[]const u8 {
    var argv: std.ArrayList([]const u8) = .empty;
    argv.appendSlice(a, &.{ "sh", "-c", "out=$1; shift; exec \"$@\" >\"$out\"", "sh", out_path, tool.exe, "-d" }) catch oom();
    if (tool.gnu) {
        if (arch == .x86_64) argv.appendSlice(a, &.{ "-w", "-M", "intel" }) catch oom();
    } else if (arch == .x86_64) {
        argv.append(a, "--x86-asm-syntax=intel") catch oom();
    }
    argv.append(a, file) catch oom();
    const r = proc.run(a, "/bin/sh", argv.items, envp, .{ .stdout_limit = 4096, .stdout_overflow = .truncate, .stderr_limit = 4096, .timeout_ms = 3_600_000 }) catch |e|
        return std.fmt.allocPrint(a, "objdump did not run ({s})", .{@errorName(e)}) catch oom();
    if (r.term == .exited and r.term.exited == 0) return null;
    const first = std.mem.sliceTo(trimSpace(r.stderr), '\n');
    return std.fmt.allocPrint(a, "objdump failed ({d}): {s}", .{ r.term.code(), first }) catch oom();
}

const FileStats = struct {
    counts: [256]u64 = @splat(0),
    first_address: [256]u64 = @splat(0),
    first_text: [256][]const u8 = @splat(""),
    instructions: u64 = 0,
    zmm: u64 = 0,
};

const Scan = struct {
    a: Allocator,
    db: *const Db,
    target: Target,
    stats: *FileStats,
    unclassified_features: *[256]u64,
    unclassified_mnemonics: *std.StringHashMapUnmanaged(u64),

    fn line(s: *Scan, raw: []const u8) void {
        const ln = parseLine(raw) orelse return;
        s.stats.instructions += 1;
        const v = switch (s.target.arch) {
            .x86_64 => classifyX86(s.db, ln),
            .aarch64 => classifyA64(s.db, ln),
        };
        if (v.zmm) s.stats.zmm += 1;
        if (v.unknown_mnemonic) {
            const gop = s.unclassified_mnemonics.getOrPut(s.a, ln.mnemonic) catch oom();
            if (!gop.found_existing) {
                gop.key_ptr.* = s.a.dupe(u8, ln.mnemonic) catch oom();
                gop.value_ptr.* = 0;
            }
            gop.value_ptr.* += 1;
        }
        var unk = v.unclassified;
        while (unk != 0) : (unk &= unk - 1) s.unclassified_features[@intCast(@ctz(unk))] += 1;
        var missing = v.need & ~s.target.has;
        while (missing != 0) : (missing &= missing - 1) {
            const f: usize = @intCast(@ctz(missing));
            if (s.stats.counts[f] == 0) {
                s.stats.first_address[f] = ln.address;
                s.stats.first_text[f] = std.fmt.allocPrint(s.a, "{s} {s}", .{ ln.mnemonic, ln.operands }) catch oom();
            }
            s.stats.counts[f] += 1;
        }
    }

    fn file(s: *Scan, path: []const u8) !void {
        const fd = try sys.openat(fsx.cwd, path, .{ .ACCMODE = .RDONLY }, 0);
        defer sys.close(fd);
        const buf = try s.a.alloc(u8, 1 << 22);
        var len: usize = 0;
        while (true) {
            const n = try sys.read(fd, buf[len..]);
            len += n;
            var start: usize = 0;
            while (std.mem.findScalar(u8, buf[start..len], '\n')) |nl| {
                s.line(buf[start .. start + nl]);
                start += nl + 1;
            }
            if (n == 0) {
                if (start < len) s.line(buf[start..len]);
                return;
            }
            std.mem.copyForwards(u8, buf[0 .. len - start], buf[start..len]);
            len -= start;
            // A line longer than the buffer holds no instruction.
            if (len == buf.len) len = 0;
        }
    }
};

/// What the command line asks for.
pub const Options = struct {
    path: []const u8,
    target: []const u8,
    json: bool = false,
    allow: ?[]const u8 = null,
    objdump: ?[]const u8 = null,
};

fn readFile(a: Allocator, path: []const u8, limit: usize) ?[]const u8 {
    const f = fsx.openRegular(fsx.cwd, path, true) catch return null;
    defer sys.close(f.fd);
    return fsx.readAll(a, f.fd, limit) catch null;
}

/// Audit the ELF files under `o.path` against `o.target`: 0 when no
/// instruction exceeds the target, 1 when one does, 2 on a usage or tool
/// error.
pub fn run(a: Allocator, o: Options, path_env: []const u8, tmpdir: []const u8, envp: proc.Envp) u8 {
    const db = Db.load(a) catch |e| cli.die("eb-local", "audit-isa tables are damaged ({s})", .{@errorName(e)});
    const target = db.target(o.target) orelse {
        cli.err("eb-local: audit-isa does not know the target '{s}'; the targets are:", .{o.target});
        for (db.targets.items) |t| cli.err(" {s}", .{t.name});
        cli.err("\n", .{});
        return 2;
    };
    const allow_text = if (o.allow) |p|
        readFile(a, p, 1 << 20) orelse cli.die("eb-local", "cannot read the allow list {s}", .{p})
    else
        default_allow;
    const allow = parseAllow(a, db, allow_text) catch oom();

    const root = fsx.absPath(a, o.path) catch oom();
    const st = fsx.statAt(fsx.cwd, root, true) catch |e| cli.die("eb-local", "cannot read {s} ({s})", .{ root, sys.describe(e) });
    var files: std.ArrayList([]const u8) = .empty;
    var errors: std.ArrayList(Problem) = .empty;
    if (st.isDir()) {
        walk(a, root, &files, &errors, 0);
    } else if (st.isReg()) {
        if (elfMachine(root, true) == null) cli.die("eb-local", "{s} is not an ELF file", .{root});
        files.append(a, root) catch oom();
    } else cli.die("eb-local", "{s} is neither a file nor a directory", .{root});

    const work = fsx.mkdtemp(a, tmpdir, "eb-local-isa-") catch |e| cli.die("eb-local", "cannot make a work directory in {s} ({s})", .{ tmpdir, @errorName(e) });
    defer fsx.deleteTree(a, fsx.cwd, work) catch {};
    const out_path = std.fs.path.join(a, &.{ work, "disassembly" }) catch oom();

    var tool: ?Tool = null;
    var tool_missing = false;
    const stats = a.create(FileStats) catch oom();
    var unclassified_features: [256]u64 = @splat(0);
    var unclassified_mnemonics: std.StringHashMapUnmanaged(u64) = .empty;
    var reports: std.ArrayList(FileReport) = .empty;
    var audited: u64 = 0;
    var skipped: u64 = 0;
    var instructions: u64 = 0;
    var zmm: u64 = 0;
    var violations: u64 = 0;
    var dispatch: u64 = 0;

    for (files.items) |path| {
        const machine = elfMachine(path, false) orelse continue;
        if (machine != target.arch.machine()) {
            skipped += 1;
            continue;
        }
        if (tool == null) {
            tool = pickTool(a, target.arch, o.objdump, path_env, envp);
            if (tool == null) {
                cli.err("eb-local: no disassembler for {s}: audit-isa needs binutils objdump that reads {s} files ('objdump -i' lists the formats) or llvm-objdump on PATH; --objdump PATH names one\n", .{ @tagName(target.arch), @tagName(target.arch) });
                tool_missing = true;
                break;
            }
        }
        if (disassemble(a, tool.?, target.arch, path, out_path, envp)) |why| {
            errors.append(a, .{ .path = path, .message = why }) catch oom();
            continue;
        }
        stats.* = .{};
        var scan: Scan = .{ .a = a, .db = db, .target = target, .stats = stats, .unclassified_features = &unclassified_features, .unclassified_mnemonics = &unclassified_mnemonics };
        scan.file(out_path) catch |e| {
            errors.append(a, .{ .path = path, .message = std.fmt.allocPrint(a, "cannot read the disassembly ({s})", .{@errorName(e)}) catch oom() }) catch oom();
            continue;
        };
        audited += 1;
        instructions += stats.instructions;
        zmm += stats.zmm;
        var findings: std.ArrayList(Finding) = .empty;
        for (stats.counts, 0..) |count, f| {
            if (count == 0) continue;
            const is_dispatch = allowed(allow, path, @intCast(f));
            if (is_dispatch) dispatch += count else violations += count;
            findings.append(a, .{
                .feature = db.nameOf(@intCast(f)),
                .count = count,
                .address = std.fmt.allocPrint(a, "0x{x}", .{stats.first_address[f]}) catch oom(),
                .instruction = stats.first_text[f],
                .dispatch = is_dispatch,
            }) catch oom();
        }
        if (findings.items.len > 0)
            reports.append(a, .{ .path = path, .instructions = stats.instructions, .zmm = stats.zmm, .findings = findings.items }) catch oom();
    }
    if (tool_missing) return 2;

    var unclassified: std.ArrayList(Unclassified) = .empty;
    for (unclassified_features, 0..) |count, f| {
        if (count > 0) unclassified.append(a, .{ .name = db.nameOf(@intCast(f)), .kind = "feature", .count = count }) catch oom();
    }
    var mit = unclassified_mnemonics.iterator();
    while (mit.next()) |e| unclassified.append(a, .{ .name = e.key_ptr.*, .kind = "mnemonic", .count = e.value_ptr.* }) catch oom();
    std.mem.sort(Unclassified, unclassified.items, {}, lessUnclassified);

    const report: Report = .{
        .target = target.name,
        .arch = @tagName(target.arch),
        .files_audited = audited,
        .files_skipped = skipped,
        .instructions = instructions,
        .zmm = zmm,
        .violation_count = violations,
        .dispatch_count = dispatch,
        .failed = violations > 0 or errors.items.len > 0,
        .files = reports.items,
        .unclassified = unclassified.items,
        .errors = errors.items,
    };
    const text = if (o.json)
        jsonout.renderLine(a, report) catch oom()
    else
        renderText(a, report) catch oom();
    sys.writeAll(1, text) catch return 2;
    if (errors.items.len > 0) return 2;
    return if (violations > 0) 1 else 0;
}

fn lessUnclassified(_: void, x: Unclassified, y: Unclassified) bool {
    if (x.count != y.count) return x.count > y.count;
    return std.mem.lessThan(u8, x.name, y.name);
}

// ---- tests ----------------------------------------------------------------

fn load(arena: *std.heap.ArenaAllocator) !*Db {
    return Db.load(arena.allocator());
}

fn needs(db: *const Db, line_text: []const u8, comptime arch: Arch) !Verdict {
    const ln = parseLine(line_text) orelse return error.NotALine;
    return switch (arch) {
        .x86_64 => classifyX86(db, ln),
        .aarch64 => classifyA64(db, ln),
    };
}

fn hasFeature(db: *const Db, v: Verdict, name: []const u8) bool {
    return v.need & bit(db.idOf(name).?) != 0;
}

test "x86 mnemonics map to the features their encoding needs" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const db = try load(&arena);
    const zmm = try needs(db, "  1f:\t62 f1 7c 48 28 c1       \tvaddps zmm0,zmm1,zmm2", .x86_64);
    try std.testing.expect(hasFeature(db, zmm, "avx512f"));
    try std.testing.expect(!hasFeature(db, zmm, "avx512vl"));
    try std.testing.expect(zmm.zmm);
    const ymm_evex = try needs(db, "  1f:\t62 f1 7c 28 58 c1       \tvaddps ymm0,ymm1,ymm2", .x86_64);
    try std.testing.expect(hasFeature(db, ymm_evex, "avx512f"));
    try std.testing.expect(hasFeature(db, ymm_evex, "avx512vl"));
    const ymm_vex = try needs(db, "  1f:\tc5 f4 58 c2             \tvaddps ymm0,ymm1,ymm2", .x86_64);
    try std.testing.expect(hasFeature(db, ymm_vex, "avx"));
    try std.testing.expect(!hasFeature(db, ymm_vex, "avx512f"));
    const gather = try needs(db, "  1f:\tc4 e2 75 90 04 80       \tvpgatherdd ymm0,DWORD PTR [rax+ymm1*4],ymm2", .x86_64);
    try std.testing.expect(hasFeature(db, gather, "avx2"));
    const crc = try needs(db, "  1f:\tf2 48 0f 38 f1 c1       \tcrc32 rax,rcx", .x86_64);
    try std.testing.expect(hasFeature(db, crc, "sse42"));
    const andn = try needs(db, "  1f:\tc4 e2 78 f2 c1          \tandn eax,eax,ecx", .x86_64);
    try std.testing.expect(hasFeature(db, andn, "bmi"));
    const mov = try needs(db, "  1f:\t48 89 f8                \tmov rax,rdi", .x86_64);
    try std.testing.expectEqual(@as(Mask, 0), mov.need);
    try std.testing.expect(!mov.unknown_mnemonic);
    const fp16 = try needs(db, "  1f:\t62 f5 7e 08 6e c0       \tvmovw xmm0,eax", .x86_64);
    try std.testing.expect(hasFeature(db, fp16, "avx512fp16"));
    const xop = try needs(db, "  1f:\t8f e8 78 85 c1 00       \tvpmacsww xmm0,xmm0,xmm1,xmm0", .x86_64);
    try std.testing.expect(hasFeature(db, xop, "xop"));
}

test "assembler aliases map to the instruction they encode" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const db = try load(&arena);
    const cmp = try needs(db, "  1f:\t62 f1 7c 48 c2 c1 01    \tvcmpltps k0,zmm0,zmm1", .x86_64);
    try std.testing.expect(hasFeature(db, cmp, "avx512f"));
    const pcmp = try needs(db, "  1f:\t62 f3 7d 48 3f c1 01    \tvpcmpltb k0,zmm0,zmm1", .x86_64);
    try std.testing.expect(hasFeature(db, pcmp, "avx512bw"));
    var buf: [32]u8 = undefined;
    try std.testing.expectEqualStrings("vpclmulqdq", aliasOf("vpclmullqlqdq", &buf).?);
    try std.testing.expectEqualStrings("cmppd", aliasOf("cmpltpd", &buf).?);
    try std.testing.expect(aliasOf("cmpsd", &buf) == null);
    try std.testing.expect(aliasOf("mov", &buf) == null);
}

test "RDSSP and INCSSP need no shadow stack" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const db = try load(&arena);
    const rdssp = try needs(db, "  1f:\tf3 48 0f 1e c8          \trdsspq rax", .x86_64);
    try std.testing.expect(!hasFeature(db, rdssp, "shstk"));
    const saveprevssp = try needs(db, "  1f:\tf3 0f 01 ea             \tsaveprevssp", .x86_64);
    try std.testing.expect(hasFeature(db, saveprevssp, "shstk"));
}

test "target feature sets" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const db = try load(&arena);
    const zen3 = db.target("x86_64/amd/zen3").?;
    const zen4 = db.target("x86_64/amd/zen4").?;
    const icelake = db.target("x86_64/intel/icelake").?;
    const generic = db.target("x86_64/generic").?;
    const has = struct {
        fn f(d: *const Db, t: Target, n: []const u8) bool {
            return t.has & bit(d.idOf(n).?) != 0;
        }
    }.f;
    try std.testing.expect(has(db, zen3, "avx2"));
    try std.testing.expect(has(db, zen3, "vaes"));
    try std.testing.expect(!has(db, zen3, "avx512f"));
    try std.testing.expect(!has(db, zen3, "avx512vl"));
    try std.testing.expect(has(db, zen4, "avx512f"));
    try std.testing.expect(has(db, zen4, "avx512bf16"));
    try std.testing.expect(!has(db, zen4, "avx512vp2intersect"));
    try std.testing.expect(!has(db, zen4, "avx512fp16"));
    try std.testing.expect(has(db, zen4, "clzero"));
    try std.testing.expect(!has(db, icelake, "avx512bf16"));
    try std.testing.expect(!has(db, icelake, "clzero"));
    try std.testing.expect(has(db, icelake, "sgx"));
    try std.testing.expect(!has(db, zen4, "sgx"));
    try std.testing.expect(has(db, icelake, "avx512vbmi"));
    try std.testing.expect(!has(db, generic, "sse3"));
    try std.testing.expect(!has(db, zen4, "fma4"));
    try std.testing.expect(db.target("zen3").?.name.len == zen3.name.len);
    try std.testing.expect(db.target("x86_64/amd/zen9") == null);
}

test "an instruction beyond the target is the features the target lacks" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const db = try load(&arena);
    const v = try needs(db, "  1f:\t62 f1 7c 28 58 c1       \tvaddps ymm0,ymm1,ymm2", .x86_64);
    const zen3 = db.target("x86_64/amd/zen3").?;
    const zen4 = db.target("x86_64/amd/zen4").?;
    const lacks3 = v.need & ~zen3.has;
    try std.testing.expect(lacks3 & bit(db.idOf("avx512f").?) != 0);
    try std.testing.expect(lacks3 & bit(db.idOf("avx512vl").?) != 0);
    try std.testing.expectEqual(@as(Mask, 0), v.need & ~zen4.has);
}

test "objdump lines parse for x86-64" {
    const a = parseLine("  1f:\t62 f2 7d 48 18 0d 00 00 00 00 \tvbroadcastss zmm1,DWORD PTR [rip+0x0]        # 29 <f+0x29>").?;
    try std.testing.expectEqual(@as(u64, 0x1f), a.address);
    try std.testing.expectEqualStrings("vbroadcastss", a.mnemonic);
    try std.testing.expectEqualStrings("zmm1,DWORD PTR [rip+0x0]", a.operands);
    try std.testing.expectEqual(@as(u8, 'E'), x86Encoding(a.bytes));
    const b = parseLine("  4a:\t66 66 2e 0f 1f 84 00 00 00 00 00 \tdata16 cs nop WORD PTR [rax+rax*1+0x0]").?;
    try std.testing.expectEqualStrings("nop", b.mnemonic);
    try std.testing.expectEqual(@as(u8, 'L'), x86Encoding(b.bytes));
    const c = parseLine("  12:\tf0 48 0f b1 0a          \tlock cmpxchg QWORD PTR [rdx],rcx").?;
    try std.testing.expectEqualStrings("cmpxchg", c.mnemonic);
    const d = parseLine("  0:\tc5 f8 77                \tvzeroupper").?;
    try std.testing.expectEqualStrings("vzeroupper", d.mnemonic);
    try std.testing.expectEqual(@as(u8, 'V'), x86Encoding(d.bytes));
    try std.testing.expectEqual(@as(u8, 'X'), x86Encoding("8f e8 78 85 c1 00"));
    try std.testing.expectEqual(@as(u8, 'L'), x86Encoding("8f 00"));
    const e = parseLine("  401000: 62 f1 7c 48 28 c1  \tvmovaps zmm0, zmm1").?;
    try std.testing.expectEqual(@as(u64, 0x401000), e.address);
    try std.testing.expectEqualStrings("zmm0, zmm1", e.operands);
    try std.testing.expect(parseLine("0000000000000000 <f>:") == null);
    try std.testing.expect(parseLine("Disassembly of section .text:") == null);
    try std.testing.expect(parseLine("") == null);
    try std.testing.expectEqual(@as(u16, 512), vectorWidth("ZMMWORD PTR [rax],zmm0"));
    try std.testing.expectEqual(@as(u16, 256), vectorWidth("ymm0,YMMWORD PTR [rax]"));
    try std.testing.expectEqual(@as(u16, 0), vectorWidth("rax,rcx"));
}

test "objdump lines parse for aarch64" {
    const g = parseLine("   4:\t4e80a400 \tsmmla\tv0.4s, v0.16b, v0.16b").?;
    try std.testing.expectEqual(@as(u64, 4), g.address);
    try std.testing.expectEqualStrings("smmla", g.mnemonic);
    try std.testing.expectEqualStrings("v0.4s, v0.16b, v0.16b", g.operands);
    const l = parseLine("       8: 5400050b     \tb.lt\t0xa4 <f+0xa4>").?;
    try std.testing.expectEqualStrings("b.lt", l.mnemonic);
    try std.testing.expectEqualStrings("0xa4", l.operands);
}

test "aarch64 mnemonics map to the features they need" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const db = try load(&arena);
    const cases = [_]struct { text: []const u8, feature: ?[]const u8 }{
        .{ .text = "  0:\t2518e3e0 \tptrue\tp0.s", .feature = "sve" },
        .{ .text = "  0:\ta5404000 \tld1w\t{z0.s}, p0/z, [x0]", .feature = "sve" },
        .{ .text = "  0:\t04e0e3e0 \tcntd\tx0", .feature = "sve" },
        .{ .text = "  0:\t4522b400 \tbdep\tz0.s, z0.s, z2.s", .feature = "sve2-bitperm" },
        .{ .text = "  0:\t4522b400 \tsmlalb\tz0.s, z1.h, z2.h", .feature = "sve2" },
        .{ .text = "  0:\t4e40fc00 \tbfdot\tv0.4s, v1.8h, v2.8h", .feature = "bf16" },
        .{ .text = "  0:\t64608000 \tbfdot\tz0.s, z0.h, z0.h", .feature = "sve-bf16" },
        .{ .text = "  0:\t4e80a400 \tsmmla\tv0.4s, v0.16b, v0.16b", .feature = "i8mm" },
        .{ .text = "  0:\t45809c00 \tsmmla\tz0.s, z0.b, z0.b", .feature = "sve-i8mm" },
        .{ .text = "  0:\t4e8f9420 \tsdot\tv0.4s, v1.16b, v15.16b", .feature = "dotprod" },
        .{ .text = "  0:\tf8e10000 \tldaddal\tx1, x0, [x0]", .feature = "lse" },
        .{ .text = "  0:\t1ac04c00 \tcrc32cx\tw0, w0, x0", .feature = "crc" },
        .{ .text = "  0:\t4e284800 \taese\tv0.16b, v0.16b", .feature = "aes" },
        .{ .text = "  0:\t0ee0e000 \tpmull\tv0.1q, v0.1d, v0.1d", .feature = "pmull" },
        .{ .text = "  0:\t4e421400 \tfadd\tv0.8h, v0.8h, v2.8h", .feature = "fp16" },
        .{ .text = "  0:\t1ee22800 \tfadd\th0, h0, h2", .feature = "fp16" },
        .{ .text = "  0:\t4ea1d400 \tfadd\tv0.4s, v0.4s, v1.4s", .feature = null },
        .{ .text = "  0:\t0e20a800 \tpmull\tv0.8h, v0.8b, v0.8b", .feature = null },
        .{ .text = "  0:\td503233f \tpaciasp", .feature = null },
        .{ .text = "  0:\tdac10800 \tpacia\tx0, x1", .feature = "pauth" },
        .{ .text = "  0:\td65f0bff \tretaa", .feature = "pauth" },
        .{ .text = "  0:\tf9400000 \tldr\tx0, [x0]", .feature = null },
    };
    for (cases) |c| {
        const v = try needs(db, c.text, .aarch64);
        if (c.feature) |f| {
            try std.testing.expect(hasFeature(db, v, f));
            try std.testing.expectEqual(@as(Mask, bit(db.idOf(f).?)), v.need);
        } else try std.testing.expectEqual(@as(Mask, 0), v.need);
    }
}

test "aarch64 targets: SVE needs neoverse_v1, SVE2 needs neoverse_v2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const db = try load(&arena);
    const n1 = db.target("aarch64/neoverse_n1").?;
    const v1 = db.target("aarch64/neoverse_v1").?;
    const v2 = db.target("aarch64/neoverse_v2").?;
    const generic = db.target("aarch64/generic").?;
    const sve = bit(db.idOf("sve").?);
    const sve2 = bit(db.idOf("sve2").?);
    try std.testing.expect(n1.has & sve == 0);
    try std.testing.expect(v1.has & sve != 0);
    try std.testing.expect(v1.has & sve2 == 0);
    try std.testing.expect(v2.has & sve2 != 0);
    try std.testing.expect(generic.has & bit(db.idOf("lse").?) == 0);
    try std.testing.expect(n1.has & bit(db.idOf("dotprod").?) != 0);
    try std.testing.expect(n1.has & bit(db.idOf("i8mm").?) == 0);
    try std.testing.expect(v1.has & bit(db.idOf("i8mm").?) != 0);
    try std.testing.expect(v1.has & bit(db.idOf("bf16").?) != 0);
    try std.testing.expect(db.target("a64fx").?.has & sve != 0);
}

test "the allow list names packages and features" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const db = try load(&arena);
    const entries = try parseAllow(a, db, default_allow);
    const rtm = db.idOf("rtm").?;
    const xop = db.idOf("xop").?;
    try std.testing.expect(allowed(entries, "/cvmfs/x/software/OpenSSL/3.0/lib/libcrypto.so", rtm));
    try std.testing.expect(!allowed(entries, "/cvmfs/x/software/OpenSSL/3.0/lib/libcrypto.so", db.idOf("avx512f").?));
    try std.testing.expect(!allowed(entries, "/cvmfs/x/software/Other/1.0/lib/libx.so", rtm));
    try std.testing.expect(allowed(entries, "/p/software/x264/1/bin/x264", xop));
    const avx512bw = db.idOf("avx512bw").?;
    try std.testing.expect(allowed(entries, "/p/software/zlib/2.3.2/lib/libz.so.1.3.1.zlib-ng", avx512bw));
    try std.testing.expect(allowed(entries, "/p/software/zlib/2.3.2/lib/libz.so.1.3.1.zlib-ng", db.idOf("avx512vnni").?));
    try std.testing.expect(!allowed(entries, "/p/software/zlib/2.3.2/lib/libz.so.1.3.1.zlib-ng", db.idOf("avx512fp16").?));
    // GROMACS: the AVX-512 FMA unit timing loops of an AVX2_256 build.
    try std.testing.expect(allowed(entries, "/p/software/GROMACS/2025.4-foss-2026.1/lib/libgromacs.so.10.0.0", db.idOf("avx512f").?));
    try std.testing.expect(allowed(entries, "/p/software/GROMACS/2025.4-foss-2026.1/lib/libgromacs_mpi_d.so.10.0.0", db.idOf("avx512f").?));
    try std.testing.expect(!allowed(entries, "/p/software/GROMACS/2025.4-foss-2026.1/lib/libgromacs.so.10.0.0", db.idOf("avx512bw").?));
    try std.testing.expect(!allowed(entries, "/p/software/GROMACS/2025.4-foss-2026.1/lib/libgromacs.so.10.0.0", db.idOf("avx512vl").?));
    const custom = try parseAllow(a, db, "Foo avx512f,nosuchfeature  # reason\n# comment\n\n");
    try std.testing.expectEqual(@as(usize, 1), custom.len);
    try std.testing.expect(allowed(custom, "/a/software/Foo/1/lib/x.so", db.idOf("avx512f").?));
}
